const adminSections=[['branches','สาขา'],['fuels','ชนิดน้ำมัน'],['tanks','ถังน้ำมัน'],['meters','มิเตอร์ / หัวจ่าย'],['users','ผู้ใช้และสิทธิ์'],['categories','หมวดรายการ'],['approvers','ผู้อนุมัติ']];function collection(type){return {branches,fuels,tanks,meters,users,categories,approvers}[type]}
function adminPage(){let list=collection(adminTab);return head('จัดการระบบ','ข้อมูลตั้งค่าตัวอย่าง · เพิ่มและปิดใช้งานได้โดยเก็บประวัติเดิม',`<button class="primary" onclick="adminForm('${adminTab}')">+ เพิ่ม${adminSections.find(s=>s[0]===adminTab)[1]}</button>`)+`<div class="tabs">${adminSections.map(([id,label])=>`<button class="${id===adminTab?'selected':''}" onclick="adminTab='${id}';render()">${label}</button>`).join('')}</div>${adminTab==='users'?'<div class="note">สิทธิ์ดูข้อมูลการเงินกับสิทธิ์จัดการระบบกำหนดแยกกัน เจ้าของสามารถมีบทบาท Admin เพิ่มได้ การสลับบทบาทด้านบนใช้บัญชีตัวอย่างที่กำหนดไว้ ไม่ได้เข้าสู่บัญชีที่เพิ่มใหม่</div>':''}${adminTab==='tanks'?'<div class="note">เลือกสาขา → รหัสและชื่อถัง → ชนิดน้ำมัน → ความจุและระดับเตือน → วันเริ่มใช้และยอดเริ่มต้น → ตรวจทาน → บันทึก</div>':''}<section class="panel">${table(['ชื่อ / รหัส','ข้อมูลที่กำหนด','สถานะ','จัดการ'],list.map(x=>`<tr><td>${esc(x.code?x.code+' · '+x.name:x.name)}</td><td>${adminDescription(adminTab,x)}</td><td>${badge(x.active?'ใช้งาน':'ปิดใช้งาน')}</td><td><div class="actions"><button onclick="adminForm('${adminTab}','${x.id}')">แก้ไข</button><button onclick="toggleAdmin('${adminTab}','${x.id}')">${x.active?'ปิดใช้งาน':'เปิดใช้งาน'}</button></div></td></tr>`))}</section><div class="note warning">ข้อมูลที่มีประวัติจะไม่ถูกลบ ถังและชนิดน้ำมันในบันทึกเดิมเก็บเป็นข้อมูล ณ วันนั้น การเพิ่มถังใหม่ไม่เปลี่ยนแบบบันทึกย้อนหลัง</div>`}
function adminDescription(type,x){if(type==='tanks')return `${bname(x.branch)} · ${fuelName(x.fuel)}<br><small>ความจุ ${fmt(x.capacity)} / เตือน ${fmt(x.warning)} ลิตร · เริ่ม ${x.start}</small>`;if(type==='users')return `${esc(x.role)} · ${bname(x.branch)}<br><small>การเงิน: ${x.financial?'ได้รับสิทธิ์':'ไม่มีสิทธิ์'}</small>`;if(type==='meters')return `${bname(x.branch)} · ${tanks.find(t=>t.id===x.tank)?.code||'ยังไม่ผูกถัง'}`;if(type==='approvers')return `${bname(x.branch)} · วงเงินไม่เกิน ${fmt(x.limit)} บาท`;return 'ข้อมูลตั้งค่าระบบ'}
let stagedAdmin=null;function adminForm(type,id){let x=collection(type).find(x=>x.id===id),extras='';if(type==='tanks')extras=selectField('สาขา','branch',branches.filter(b=>b.active),x?.branch||'b1')+field('รหัสถัง','code',x?.code||'','text','required')+selectField('ชนิดน้ำมัน','fuel',fuels.filter(f=>f.active||f.id===x?.fuel),x?.fuel||'f1')+field('ความจุ (ลิตร)','capacity',x?.capacity||20000,'number','required min="1" step="0.01"')+field('ระดับแจ้งเตือน (ลิตร)','warning',x?.warning||4000,'number','required min="0" step="0.01"')+field('วันเริ่มใช้งาน / มีผล','start',x?.start||TODAY,'date','required')+field('ยอดเริ่มต้น (ลิตร)','opening',x?.opening||0,'number','required min="0" step="0.01"');if(type==='meters')extras=selectField('สาขา','branch',branches.filter(b=>b.active),x?.branch||'b1')+selectField('ถังที่เชื่อมต่อ','tank',tanks.filter(t=>t.active).map(t=>({id:t.id,name:bname(t.branch)+' / '+t.code+' '+fuelName(t.fuel)})),x?.tank||'t1');if(type==='users')extras=selectField('บทบาท','role',[...roles,'เจ้าของ + Admin'].map(r=>({id:r,name:r})),x?.role||'พนักงาน')+selectField('สิทธิ์สาขา','branch',[{id:'all',name:'ทุกสาขา'},...branches],x?.branch||'b1')+`<label class="checkrow"><input name="financial" type="checkbox" ${x?.financial?'checked':''}> ให้สิทธิ์ดูข้อมูลการเงิน</label><div class="note wide">สิทธิ์กระทำตามบทบาทดูได้ในคู่มือระบบ รุ่นจริงจะเลือกหลายสาขาและกำหนดสิทธิ์อ่าน/สร้าง/แก้ไข/อนุมัติ/ส่งออกแยกรายเมนู</div>`;if(type==='approvers')extras=selectField('ขอบเขตสาขา','branch',[{id:'all',name:'ทุกสาขา'},...branches],x?.branch||'b1')+field('วงเงินอนุมัติสูงสุด (บาท)','limit',x?.limit||3000,'number','required min="0" step="0.01"');modal(`${x?'แก้ไข':'เพิ่ม'}${adminSections.find(s=>s[0]===type)[1]}`,`<form onsubmit="event.preventDefault();stageAdmin(this,'${type}','${id||''}')"><div class="formgrid">${field(type==='approvers'?'ชื่อผู้อนุมัติ (ต้องตรงกับผู้ใช้)':'ชื่อ','name',x?.name||'','text','required')}${extras}</div>${x&&type==='tanks'?'<div class="note warning">เมื่อเปลี่ยนชนิดน้ำมัน ต้องระบุวันที่มีผลและยอดเปิดใหม่ บันทึกเก่ายังคงชนิดเดิม การย้ายสาขาหรือย้อนวันที่ถังที่มีประวัติไม่อนุญาตในต้นแบบ</div>':''}<div id="adminError"></div><button class="primary">ตรวจทาน →</button></form>`)}
function stageAdmin(form,type,id){let x=Object.fromEntries(new FormData(form)),old=collection(type).find(x=>x.id===id),error='';for(let k of ['capacity','warning','opening','limit'])if(k in x)x[k]=Number(x[k]);if(type==='users')x.financial=form.financial.checked;if(type==='tanks'){if(x.warning>x.capacity||x.opening>x.capacity)error='ยอดเริ่มต้นและระดับเตือนต้องไม่เกินความจุ';else if(tanks.some(t=>t.id!==id&&t.branch===x.branch&&t.code===x.code))error='รหัสถังซ้ำในสาขานี้';else if(old&&old.branch!==x.branch)error='ถังเดิมย้ายสาขาไม่ได้ ให้ปิดใช้งานและสร้างถังใหม่';else if(old&&x.start<old.start)error='วันที่มีผลต้องไม่ย้อนหลังไปก่อนวันเริ่มเดิม';else if(old&&old.fuel!==x.fuel&&Object.values(days).some(d=>d.date>=x.start&&d.lines.some(l=>l.tank===id)))error='มีบันทึกตั้งแต่วันที่มีผลแล้ว ให้ใช้วันที่ถัดจากบันทึกล่าสุดเพื่อรักษาประวัติ';}if(type==='meters'&&tanks.find(t=>t.id===x.tank)?.branch!==x.branch)error='หัวจ่ายต้องเชื่อมกับถังในสาขาเดียวกัน';if(type==='approvers'&&!users.some(u=>u.name===x.name&&u.active))error='ต้องระบุชื่อผู้ใช้ที่มีอยู่และเปิดใช้งาน';if(error){$('#adminError').innerHTML=`<div class="note error">${error}</div>`;return}stagedAdmin={type,id,x};modal('ตรวจทานข้อมูลก่อนบันทึก',`<h3>${esc(x.name)}</h3><p>${adminDescription(type,x)}</p>${type==='tanks'?`<p>ยอดเริ่มต้น ${fmt(x.opening)} ลิตร · มีผล ${x.start}</p><div class="note">ถังจะปรากฏในแบบบันทึกใหม่ตั้งแต่วันที่มีผล บันทึกที่สร้างแล้วจะคงรายการถังเดิม</div>`:''}<div class="actions"><button onclick="adminForm('${type}','${id}')">กลับไปกรอกใหม่</button><button class="primary" onclick="commitAdmin()">ยืนยันบันทึก</button></div>`)}
function commitAdmin(){let {type,id,x}=stagedAdmin,old=collection(type).find(x=>x.id===id);if(old){log('แก้ไขข้อมูลตั้งค่า',`${type} ${old.name} · ก่อน: ${JSON.stringify(old)} · หลัง: ${JSON.stringify(x)}`,x.branch||'all');if(type==='tanks'&&old.fuel!==x.fuel){old.fuelHistory??=[];old.fuelHistory.push({fuel:old.fuel,start:old.start,end:x.start})}Object.assign(old,x)}else{collection(type).push({...x,id:type+'-'+Date.now(),active:true});log('เพิ่มข้อมูลตั้งค่า',`${type} · ${x.name}`,x.branch||'all')}closeModal();render();toast('บันทึกข้อมูลตั้งค่าจำลองแล้ว')}
function toggleAdmin(type,id){let x=collection(type).find(x=>x.id===id);if(x.active&&type==='fuels'&&tanks.some(t=>t.active&&t.fuel===id))return toast('ยังมีถังใช้งานชนิดนี้ กรุณาปิดถังหรือเปลี่ยนชนิดพร้อมวันที่มีผลก่อน');if(x.active&&type==='branches'&&tanks.some(t=>t.active&&t.branch===id))return toast('ยังมีถังใช้งานในสาขา กรุณาปิดถังก่อน');modal(x.active?'ปิดใช้งานข้อมูล':'เปิดใช้งานข้อมูล',`<p>${esc(x.name)} · ประวัติเดิมยังอยู่</p><button class="primary" onclick="confirmToggle('${type}','${id}')">ยืนยัน${x.active?'ปิด':'เปิด'}ใช้งาน</button>`)}function confirmToggle(type,id){let x=collection(type).find(x=>x.id===id);x.active=!x.active;log(x.active?'เปิดใช้งาน':'ปิดใช้งาน',`${type}: ${x.name}`,x.branch||'all');closeModal();render()}
function reportData(){return optionsBranches().filter(b=>scope(b.id)).map(b=>{let ds=Object.values(days).filter(d=>d.branch===b.id&&(reportPeriod==='day'?d.date===TODAY:d.date.startsWith('2026-09')));let sum=k=>ds.reduce((s,d)=>s+Number(d[k]||0),0);let ending=days[b.id+'|'+(reportPeriod==='day'?TODAY:'2026-09-30')];return {branch:b.name,sales:ds.length?sum('sales'):null,received:ds.length?sum('cash')+sum('transfer')+sum('card'):null,expense:finance.filter(f=>f.branch===b.id&&f.type==='รายจ่าย'&&f.status==='ตรวจแล้ว'&&(reportPeriod==='day'?f.date===TODAY:f.date.startsWith('2026-09'))).reduce((s,f)=>s+f.amount,0),ending:ending&&ending.level==='tank'?ending.lines.reduce((s,l)=>s+balance(l,ending.date),0):null,pending:requests.filter(r=>r.branch===b.id&&['รอหลักฐาน','รอตรวจเคลียร์','รอจ่ายส่วนต่าง'].includes(r.status)).reduce((s,r)=>s+r.amount,0),status:ds.length?ds.every(d=>d.status==='ปิดวันแล้ว')?'ปิดวันแล้ว':'มีข้อมูลยังไม่ปิดวัน':'รอข้อมูล',updated:ds.length?ds.map(d=>d.updated).at(-1):'ยังไม่มีข้อมูล'}})}
function reportsPage(){let data=reportData();return head('รายงานและ Excel','รายงานจากข้อมูลสมมติที่มีในต้นแบบ',`<button onclick="importStep=0;go('import')">นำเข้า Excel เก่า</button><button class="primary" onclick="exportPreview()">ส่งออก Excel</button>`)+`<div class="filters">${branchFilter()}<select aria-label="ช่วงรายงาน" onchange="reportPeriod=this.value;render()"><option value="day" ${reportPeriod==='day'?'selected':''}>รายวัน · 27 ก.ย. 2569</option><option value="month" ${reportPeriod==='month'?'selected':''}>รายเดือน · กันยายน 2569</option></select></div>${reportPeriod==='month'?'<div class="note warning">เดือนนี้ยังไม่สิ้นสุด มีข้อมูลตัวอย่างเพียง 26–27 ก.ย. ยอดน้ำมันสิ้นเดือนแสดง “รอข้อมูล” จนมีข้อมูล 30 ก.ย. ไม่รวมยอดคงเหลือรายวันเข้าด้วยกัน</div>':''}<section class="panel">${table(['สาขา','ยอดขาย (บาท)','เงินรับจากยอดขาย','รายจ่ายตรวจแล้ว','น้ำมันปลายงวด (ลิตร)','เงินเบิกค้าง','สถานะ'],data.map(r=>`<tr><td>${r.branch}<br><small>ล่าสุด ${r.updated}</small></td><td>${r.sales===null?'รอข้อมูล':fmt(r.sales)}</td><td>${r.received===null?'รอข้อมูล':fmt(r.received)}</td><td>${fmt(r.expense)}</td><td>${r.ending===null?'รอข้อมูล':fmt(r.ending)}</td><td>${fmt(r.pending)}</td><td>${badge(r.status)}</td></tr>`))}</section><section class="panel"><h2>ถังที่เกี่ยวข้องกับรายงาน</h2>${table(['สาขา','ถัง','ชนิดน้ำมัน','วันเริ่มใช้','ยอดล่าสุด'],tanks.filter(t=>scope(t.branch)).map(t=>`<tr><td>${bname(t.branch)}</td><td>${t.code}</td><td>${fuelName(t.fuel)}</td><td>${t.start}</td><td>${tankBalance(t).calc===null?'รอข้อมูล':fmt(tankBalance(t).calc)+' ลิตร'}</td></tr>`))}</section><div class="note">เงินรับในตารางเป็นเงินรับจากยอดขายของงวด ไม่รวมโอนภายในหรือเงินทดรอง รายงานจริงต้องแยกวันที่ขาย วันที่รับชำระหนี้ และวันที่จ่ายเงินให้ตรวจสอบได้</div>`}
function exportPreview(){modal('ตัวอย่างส่งออก Excel',`<p>ขอบเขต: ${branch==='all'?'ทุกสาขาที่ได้รับสิทธิ์':bname(branch)} · ${reportPeriod==='day'?'27 กันยายน 2569':'กันยายน 2569'}</p><p>ไฟล์จริงจะมีแผ่นงานยอดขาย น้ำมัน เงินรับ รายจ่าย และเงินทดรอง พร้อมสถานะและเวลาตัดข้อมูล</p><div class="note warning">ต้นแบบจำลองการ Export เท่านั้น ไม่ได้สร้างไฟล์ .xlsx และไม่มีการซิงก์กลับจาก Excel ที่แก้ไข</div><button class="primary" onclick="closeModal();log('จำลองส่งออกรายงาน','ไม่มีไฟล์จริง');toast('จำลองส่งออกสำเร็จ · ระบบจริงจะดาวน์โหลดไฟล์ Excel')">ทดลองยืนยันส่งออก</button>`)}
function importPage(){let body='';if(importStep===0)body=`<form onsubmit="event.preventDefault();if(!this.file.files.length)return;importFile=this.file.files[0].name;importBranch=this.branch.value;importStep=1;render()">${selectField('สาขาที่จะนำเข้า','branch',optionsBranches(),importBranch)}<div class="field"><label>เลือก Excel เดิม (.xlsx / .xls)</label><input name="file" type="file" accept=".xlsx,.xls" required></div><div class="note">จำลองขั้นตอนด้วยแถวตัวอย่าง ไม่อ่านเนื้อหาไฟล์จริง รูปแบบนำเข้าจะกำหนดหลังตรวจไฟล์เดิมของแต่ละสาขา</div><button class="primary">ถัดไป: จับคู่ข้อมูล</button></form>`;if(importStep===1)body=`<h3>${esc(importFile)} · ${bname(importBranch)}</h3><form onsubmit="event.preventDefault();if(new Set([...this.querySelectorAll('select')].map(s=>s.value)).size!==3){toast('คอลัมน์ต้นทางต้องไม่ซ้ำกัน');return}importStep=2;render()">${['วันที่','ยอดขาย','เงินสด'].map((s,i)=>selectField(s,'map'+i,['วันที่','ขายรวม','สด'].map(c=>({id:c,name:c})),['วันที่','ขายรวม','สด'][i])).join('')}<button class="primary">ตรวจตัวอย่างและข้อผิดพลาด</button></form>`;if(importStep===2)body=`${table(['แถว','วันที่','ยอดขาย','ผลตรวจ'],['<tr><td>2</td><td>25 ก.ย. 2569</td><td>88,000</td><td>'+badge('พร้อมนำเข้า')+'</td></tr>','<tr><td>3</td><td>27 ก.ย. 2569</td><td>110,000</td><td>'+badge('อาจซ้ำ: สาขา + วันที่')+'</td></tr>','<tr><td>4</td><td>วันที่ไม่ถูกต้อง</td><td>—</td><td>'+badge('กรอกผิด')+'</td></tr>'])}<form onsubmit="event.preventDefault();importStep=3;render()"><label class="checkrow"><input type="checkbox" required> ตรวจแล้ว: ข้ามรายการที่อาจซ้ำ ไม่เขียนทับข้อมูลเดิม</label><label class="checkrow"><input type="checkbox" required> ข้ามแถวที่ผิด และนำกลับไปแก้ไขในไฟล์ต้นทาง</label><button class="primary">ยืนยันจำลองนำเข้า 1 แถว</button></form>`;if(importStep===3)body='<h2>ตรวจเสร็จแล้ว</h2><p>จำลองนำเข้าสำเร็จ 1 แถว · ข้ามซ้ำ 1 แถว · ข้ามข้อผิดพลาด 1 แถว</p><div class="note">ไม่มีการเขียนข้อมูลจากไฟล์จริงหรือเพิ่มยอดเข้ารายงานต้นแบบ</div><button class="primary" onclick="go(\'reports\')">กลับไปรายงาน</button>';return head('นำเข้าข้อมูลเก่าจาก Excel','ตรวจข้อมูลก่อนบันทึกทุกครั้ง')+`<div class="steps">${['สาขาและไฟล์','จับคู่ข้อมูล','ตรวจและยืนยัน','ผลการนำเข้า'].map((s,i)=>`<span class="step ${i===importStep?'current':''}">${i+1}. ${s}</span>`).join('')}</div><section class="panel">${body}${importStep>0&&importStep<3?'<button style="margin-top:15px" onclick="importStep--;render()">ย้อนกลับ</button>':''}</section>`}
function auditPage(){return head('ประวัติการทำรายการ','ประวัติจำลองในแท็บนี้ · ระบบจริงต้องเก็บผู้กระทำ เวลา และค่าก่อน–หลังอย่างแก้ย้อนหลังไม่ได้')+`<div class="filters">${branchFilter()}</div><section class="panel">${table(['เวลา','ผู้กระทำ','สาขา','การกระทำ','รายละเอียด'],audit.filter(a=>(scope(a.branch)||a.branch==='all')&&(role!=='Admin'||/ตั้งค่า|ใช้งาน/.test(a.action))).map(a=>`<tr><td>${a.time}</td><td>${a.role}</td><td>${bname(a.branch)}</td><td>${a.action}</td><td style="max-width:400px;overflow-wrap:anywhere">${esc(a.detail)}</td></tr>`))}</section>`}
function loginPage(){return `<div class="login"><div class="brand"><div class="mark">ต</div><div><strong>ไตยสยาม</strong><small>ระบบงานปั๊มน้ำมันครอบครัว</small></div></div><h1>${route==='recover'?'กู้คืนรหัสผ่าน':'เข้าสู่ระบบ'}</h1><p class="muted">${route==='recover'?'กรอกอีเมลที่ใช้สมัครงานในระบบ':'เลือกบทบาทเพื่อทดลองการทำงาน'}</p><form onsubmit="event.preventDefault();${route==='recover'?"recoverDemo()":"setRole(this.elements['role'].value);go('tasks')"}">${field('อีเมลตัวอย่าง','email','demo@taisiam.example','email','required')}${route==='recover'?'':field('รหัสผ่านตัวอย่าง (กรอกอะไรก็ได้)','password','demo1234','password','required')+selectField('ทดลองเป็น','role',roles.map(r=>({id:r,name:r})),role)}<div class="note">เป็นหน้าจอจำลอง ไม่มีบัญชีจริง ไม่มีการตรวจรหัสผ่านหรือส่งอีเมล กรุณาไม่ใช้รหัสผ่านจริง</div><button class="primary" style="width:100%">${route==='recover'?'จำลองส่งลิงก์กู้คืน':'เข้าสู่พื้นที่ทำงานจำลอง →'}</button></form><button style="border:0;margin-top:14px" onclick="go('${route==='recover'?'login':'recover'}')">${route==='recover'?'กลับหน้าเข้าสู่ระบบ':'ลืมรหัสผ่าน'}</button></div>`}function recoverDemo(){modal('คำขอกู้คืนรหัสผ่าน',`<p>หากอีเมลนี้มีอยู่ในระบบจริง ผู้ใช้จะได้รับลิงก์ตั้งรหัสผ่านใหม่ที่มีวันหมดอายุ</p><div class="note">ต้นแบบไม่ส่งอีเมลและไม่เปลี่ยนรหัสผ่าน</div><button class="primary" onclick="closeModal();go('login')">กลับหน้าเข้าสู่ระบบ</button>`)}
const permissionRows=[['งานของฉัน','ทุกสาขา','งานตั้งค่า','สาขาที่รับผิดชอบ','สาขาที่รับผิดชอบ','สาขาที่ได้รับสิทธิ์'],['ภาพรวม / การเงิน','ดูทุกสาขา','ต้องให้สิทธิ์เพิ่ม','ตามสิทธิ์เพิ่ม','ไม่มี','ดู / บันทึก / ตรวจ'],['ประจำวัน','ดู / เปิดแก้ย้อนหลัง','ไม่มี','ตรวจ / ส่งกลับ / ปิด','ร่าง / แก้ส่งกลับ / ส่งตรวจ','ดู / กระทบยอด'],['น้ำมันรับเข้า / เบิกใช้','ดู / อนุมัติ','ตั้งค่าถัง','ดู / อนุมัติตามสิทธิ์','สร้าง / ติดตาม','ดูผ่านรายงาน'],['เบิกเงิน','อนุมัติ / ติดตาม','ไม่มี','อนุมัติตามวงเงิน','สร้าง / ส่งหลักฐาน','จ่าย / ตรวจเคลียร์ / ปิด'],['รายงาน / Excel','ดู / ส่งออก / นำเข้า','ไม่มีโดยปริยาย','สาขาที่รับผิดชอบ','ไม่มี','ตามสิทธิ์สาขา'],['จัดการระบบ','เมื่อมี Admin ด้วย','สร้าง / แก้ / ปิดใช้งาน','ไม่มี','ไม่มี','ไม่มี'],['ประวัติ','ทุกสาขา','เฉพาะตั้งค่า','สาขาที่รับผิดชอบ','ประวัติรายการของตน','สาขาที่ได้รับสิทธิ์']];
function guidePage(){return head('คู่มือทดลองและแผนระบบ','ต้นแบบฉบับออกแบบ · ยังไม่ใช่ระบบใช้งานจริง',`<button onclick="go('login')">ทดลองเข้าสู่ระบบ</button>`)+`<div class="longtext"><section class="panel"><h2>เริ่มทดลอง 3 เส้นทางหลัก</h2><ol><li><b>ปิดวัน:</b> เลือกพนักงาน → บันทึกประจำวัน → อ่านเหตุผลที่ส่งกลับ → ใส่หมายเหตุผลต่างน้ำมัน → บันทึกร่าง → ตรวจทาน → ส่งตรวจ → สลับผู้จัดการ → ส่งกลับหรือปิดวัน</li><li><b>เคลียร์เงินเบิก:</b> เจ้าของอนุมัติ REQ-001 → นักบัญชีบันทึกจ่าย → พนักงานแนบหลักฐาน ใช้จริง 1,850 คืน 150 → นักบัญชีตรวจและปิด → ตรวจรายจ่าย 1,850 บาทเพียงรายการเดียว หรือเริ่มที่ REQ-002 ซึ่งจ่ายแล้ว</li><li><b>เพิ่มถัง:</b> Admin → ถังน้ำมัน → เพิ่มและตรวจทาน → เลือกวันเริ่มใช้ → บันทึก → เปลี่ยนเป็นพนักงานและเลือกวันใหม่ที่ยังไม่มีบันทึก ถังใหม่จะปรากฏ บันทึกเก่าไม่เปลี่ยน</li></ol><div class="actions"><button onclick="setRole('พนักงาน');branch='b1';go('daily')">ทดลองบันทึกประจำวัน</button><button onclick="setRole('เจ้าของ');reqFilter='all';go('requests')">ทดลองเบิกเงิน</button><button onclick="setRole('Admin');go('admin')">ทดลองเพิ่มถัง</button></div></section><section class="panel"><h2>ทดลองสถานะพิเศษ</h2><p>“กำลังบันทึก” แสดงชั่วครู่เมื่อบันทึกประจำวัน สถานะกรอกผิดจะรักษาค่าที่กรอกไว้</p><div class="actions"><button onclick="failNext=true;setRole('พนักงาน');branch='b1';go('daily');toast('การบันทึกครั้งถัดไปจะจำลองล้มเหลว')">จำลองบันทึกไม่สำเร็จ</button><button onclick="setRole('เจ้าของ');branch='b4';go('daily')">ดูสถานะรอข้อมูล</button><button onclick="location.reload()">เริ่มข้อมูลตัวอย่างใหม่</button></div><p class="filehint">รีเฟรชจะล้างการเปลี่ยนแปลงทั้งหมด ต้นแบบเก็บค่าในหน่วยความจำแท็บนี้ ไม่มีฐานข้อมูลหรือการซิงก์หลายเครื่อง</p></section><section class="panel"><h2>แผนผังเว็บไซต์</h2><p>เข้าสู่ระบบ → กู้คืนรหัสผ่าน / งานของฉันตามบทบาท</p>${table(['เมนู','หน้ารองและปลายทาง'],[['งานของฉัน','งานค้าง → รายการหรือแบบบันทึกที่ต้องทำ'],['ภาพรวมธุรกิจ','สรุป → คำขอรออนุมัติ / สาขาที่ยังไม่ส่ง / ถัง'],['สาขาและถังน้ำมัน','รายการ → รายละเอียดถัง → ประวัติ → บันทึกประจำวัน'],['บันทึกประจำวัน','เลือกสาขา–วัน → กรอก → ร่าง → ตรวจทาน → ส่งตรวจ → ปิด / ส่งกลับ'],['รับน้ำมันเข้า / เบิกใช้','รายการ → เพิ่ม → รายละเอียด / อนุมัติ → สรุปวัน'],['รายรับ–รายจ่าย','ค้นหาและกรอง → เพิ่ม / รายละเอียด / แก้ไข / ตรวจ'],['เบิกเงินและอนุมัติ','คำขอ → อนุมัติ → จ่าย → หลักฐาน / คืน / ส่วนต่าง → ปิด'],['รายงานและ Excel','รายวัน / เดือน → ส่งออกจำลอง / นำเข้า 4 ขั้น'],['จัดการระบบ','7 หมวด → รายการ → แบบฟอร์ม → ตรวจทาน → บันทึก / ปิดใช้งาน'],['ประวัติการทำรายการ','กรองสาขา → ผู้กระทำ เวลา เหตุผล และข้อมูลก่อน–หลัง']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`))}</section><section class="panel"><h2>ตารางสิทธิ์ตามบทบาท</h2>${table(['งาน','เจ้าของ','Admin','ผู้จัดการ','พนักงาน','นักบัญชี'],permissionRows.map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>'))}<div class="note">ต้นแบบซ่อนเมนู/ปุ่มและจำกัดพนักงานกับผู้จัดการตัวอย่างที่สาขา 01 เท่านั้น ระบบจริงต้องตรวจสิทธิ์ฝั่งระบบทุกคำขอ รวมถึงไฟล์ รายงาน และขอบเขตสาขา ห้ามพึ่งการซ่อนปุ่ม</div></section><section class="panel"><h2>ขอบเขตการจำลอง</h2><p><b>ทดลองได้ในแท็บนี้:</b> การเปลี่ยนสถานะประจำวัน สูตรคงเหลือ การอนุมัติและเคลียร์เงินเบิก รายรับ–รายจ่าย การเพิ่มตั้งค่าและประวัติ รวมถึงหน้ามือถือ</p><p><b>จำลองหน้าจอเท่านั้น:</b> เข้าสู่ระบบ กู้รหัสผ่าน อัปโหลดหลักฐาน (เก็บเฉพาะชื่อไฟล์) Import / Export Excel การแจ้งเตือน และสิทธิ์ของบัญชีที่เพิ่มใหม่</p><p><b>ยังต้องพัฒนา:</b> ฐานข้อมูล การยืนยันตัวตน การตรวจสิทธิ์ฝั่งระบบ จัดเก็บเอกสาร ตรวจไฟล์ บันทึกประวัติแก้ไขถาวร การสำรอง–กู้คืน ล็อกรายการและป้องกันส่งซ้ำ การทำงานพร้อมกันหลายคน และกู้ร่างหลังเครือข่ายหลุด</p></section><section class="panel"><h2>รุ่นแรก / พัฒนาภายหลัง</h2><p><b>รุ่นแรก:</b> ทั้ง 5 บทบาทและสิทธิ์สาขา ตั้งค่าถัง–น้ำมัน–หัวจ่าย บันทึกและปิดวัน รับเข้า–เบิกใช้ กระทบยอดขาย เงินทดรองครบวงจร รายงานรายวัน–เดือน นำเข้าไฟล์เก่าแบบตรวจสอบ ส่งออก Excel ประวัติและสำรองข้อมูล</p><p><b>ภายหลัง:</b> เชื่อมเครื่องขายหรือเซนเซอร์ OCR ใบเสร็จ เชื่อมธนาคาร/บัญชี แจ้งเตือนภายนอก และทำงานออฟไลน์ การโอนน้ำมันระหว่างสาขาแบบจับคู่เอกสาร หากมีการใช้งานจริงควรย้ายเข้ารุ่นแรก</p></section><section class="panel"><h2>เรื่องที่ต้องยืนยันก่อนพัฒนา</h2><ol><li>ชื่อ 4 สาขา จำนวนถัง ชนิดน้ำมัน ความจุ ระดับเตือน วันที่และยอดเริ่มต้น</li><li>มิเตอร์ / หัวจ่ายผูกกับถังอย่างไร มียอดขายระดับถังหรือเฉพาะชนิดน้ำมัน</li><li>ตัวอย่าง Excel เดิมทุกสาขา คอลัมน์ หน่วย วันที่ และกติกาคีย์ซ้ำ</li><li>ผู้ใช้และสาขาที่รับผิดชอบ วงเงินอนุมัติ ผู้แทน และการอนุมัติคำขอตนเอง</li><li>เวลาตัดวัน ผลต่างที่ยอมรับได้ วิธีวัดจริง ใครเปิดแก้ย้อนหลังได้</li><li>วิธีขายเชื่อ ลูกหนี้ การรับชำระ ค่าธรรมเนียมบัตร ภาษี ต้นทุนน้ำมัน และนโยบายลงบัญชี</li><li>การโอนน้ำมันและเงินระหว่างสาขา ใช้จริงหรือไม่ และใครตรวจปลายทาง</li><li>เอกสารที่ต้องเก็บ อายุเก็บ สำรองข้อมูล เป้าหมายกู้คืน และอุปกรณ์/เครือข่ายของพนักงาน</li></ol></section></div>`}
const oldGo=go;go=function(r){if(!['guide','login','recover'].includes(r)&&!allowed().includes(r==='import'?'reports':r)){toast('บทบาทนี้ไม่ได้รับสิทธิ์เข้าหน้านี้');return}route=r;dailyReview=false;location.hash=r;render();window.scrollTo(0,0)};
render=function(){if(['login','recover'].includes(route)){$('#app').innerHTML=loginPage();return}const current=menus.find(m=>m[0]===route);let content=({tasks,overview,tanks:tanksPage,daily:dailyPage,receive:()=>movementPage('receive'),use:()=>movementPage('use'),requests:requestsPage,finance:financePage,reports:reportsPage,admin:adminPage,audit:auditPage,guide:guidePage,import:importPage}[route]||tasks)();$('#app').innerHTML=`<div class="shell"><aside><div class="brand"><div class="mark">ต</div><div><strong>ไตยสยาม</strong><small>ระบบงานปั๊มน้ำมันครอบครัว</small></div></div><div><div class="navlabel">พื้นที่ทำงาน</div><nav class="nav">${menus.filter(m=>allowed().includes(m[0])).map(m=>`<button class="${route===m[0]?'active':''}" onclick="go('${m[0]}')"><span class="ico">${m[1]}</span>${m[2]}</button>`).join('')}</nav></div><div class="sidebottom">4 สาขา · ทำงานไปด้วยกัน<br>ต้นแบบฉบับออกแบบ / 01<br><button onclick="go('login')">ออกจากระบบจำลอง</button></div></aside><div class="workspace"><header class="topbar"><div class="actions"><button class="mobilemenu" aria-label="เปิดเมนู" onclick="document.querySelector('aside').classList.toggle('open')">☰</button><span>${current?.[2]||'คู่มือระบบ'}</span></div><div class="profile"><small>ทดลองบทบาท</small><select aria-label="ทดลองบทบาท" onchange="setRole(this.value);go('tasks')">${roles.map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select><div class="avatar">${role[0]}</div></div></header><main>${content}</main></div></div>`};
window.addEventListener('hashchange',()=>{let target=location.hash.slice(1);if(target!==route){if(['guide','login','recover'].includes(target)||allowed().includes(target==='import'?'reports':target)){route=target;render()}}});route='login';render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'navigate_prototype',description:'Open an allowed screen of the local Thai fuel-station design prototype. Does not create or submit records.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:menus.map(m=>m[0]).concat('guide')}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({screen})=>{if(screen!=='guide'&&!allowed().includes(screen))throw new Error('Screen unavailable for current role');go(screen);return {screen:route,role,simulation:true}}})}catch{}}
